symbols.possible:
possible = {
		always = no
		exists = c:JAP
		c:JAP ?= {
			NOR = {
				has_law_or_variant = law_type:law_isolationism
				has_law_or_variant = law_type:law_closed_borders
			}
		}
		exists = c:RYU
		exists = c:CHI
	}

possible = {
        OR = { c:JAP ?= this c:JTK ?= this c:JIM ?= this }
        has_global_variable = nesnd_south_settled
        NOT = { has_variable = nesnd_japan_unity_entered }
    }

possible = {
        NOT = { has_global_variable = nesnd_japan_collapse_journal_started }
        NOT = { has_global_variable = nesnd_japan_partitioned }
        nesnd_japan_at_war_with_wu = yes
    }

symbols.trigger:
trigger = {
		exists = c:JAP
		c:JAP ?= This
		OR = {
			has_law_or_variant = law_type:law_isolationism
			has_law = law_type:law_sakoku
		}
		NOT = { has_variable = flavorJAP_ce_1_var }
		is_subject = no
	}

trigger = {
		game_date >= 1840.1.1 # sanity check?
		ruler ?= {
			has_template = JAP_toyotomi_hideharu
		}
		NOT = { has_variable = flavorJAP_ce_2_var }
	}

trigger = {
		game_date >= 1846.1.1 # sanity check?
		ruler ?= {
			has_template = JAP_toyotomi_shimei
		}
		NOT = { has_variable = flavorJAP_ce_3_var }
	}

trigger = {
		exists = c:CHI 
		exists = c:JAP
		OR = {
			c:CHI ?= this
			c:JAP ?= this
		}
        AND = {
            c:JAP ?= { has_modifier = modifier_ryukyu_rivalry_officer_training }
            c:CHI ?= { has_modifier = modifier_ryukyu_rivalry_officer_training }
        }
		NOT = { exists = global_var:ryukyu_rivalry_training_incident }
	}

